-- Bestiary: Volume II: DM-only monster data for the handbook.
-- Run this in the Supabase SQL editor after setup.sql. It's safe to run again: it replaces the data.
-- Only accounts with profiles.is_admin = true can read or change these rows, so players can't see them.

create table if not exists public.bestiary (
  key        text primary key,
  data       jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.bestiary enable row level security;

drop policy if exists "bestiary: DM reads" on public.bestiary;
create policy "bestiary: DM reads" on public.bestiary
  for select to authenticated using (public.is_admin());

drop policy if exists "bestiary: DM edits" on public.bestiary;
create policy "bestiary: DM edits" on public.bestiary
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

revoke all on public.bestiary from anon;

insert into public.bestiary (key, data) values ('bestiary-2', $bx${"source":"Bestiary: Volume II (Nov 19, 2026)","volume":2,"count":300,"counts":{"creature":250,"named":50},"intro":{"title":"Using Volume II","md":"Volume II adds 250 original creatures and 50 named monsters, from KR 1 to KR 300. Everything here is new to this world: there are no classic staples.\n\nAll of Volume I's rules still apply, and aren't repeated here: Kill Rating and the Group multiplier, Running monsters, the Status effects table, the KR budget, Harvest values, and the Alpha, Minion and Boss templates. Every stat block follows the same layout, tuned to the same budget.\n\n\n### New in Volume II\n\n\nMany creatures in this book use three new mechanics. They exist to give each fight a puzzle, not just a pile of HP.\n\n- **Weak Point**: a part of the creature that can be targeted on its own. Attacks against it are made at disadvantage, but they ignore Min hit. A weak point has its own HP, and breaking it shuts down the ability listed with it. Damage to a weak point also comes off the creature's HP.\n- **Countdown**: something that will happen after a set number of rounds unless the party stops it. Show it openly: put a die on the table counting down. When it reaches 0, the listed effect happens.\n- **Shift**: the creature switches between two modes, each with its own rules. The stat block says what triggers the switch. Learning the trigger is often how you win.\n\n\n### Family structure\n\n\nCreatures are grouped into 22 families. Each family runs from low KR to high KR, so a campaign can keep meeting the same family as it grows: the small ones early on, their elders and kings later."},"mechanics":{"weak-point":{"name":"Weak Point","text":"a part of the creature that can be targeted on its own. Attacks against it are made at disadvantage, but they ignore Min hit. A weak point has its own HP, and breaking it shuts down the ability listed with it. Damage to a weak point also comes off the creature's HP."},"countdown":{"name":"Countdown","text":"something that will happen after a set number of rounds unless the party stops it. Show it openly: put a die on the table counting down. When it reaches 0, the listed effect happens."},"shift":{"name":"Shift","text":"the creature switches between two modes, each with its own rules. The stat block says what triggers the switch. Learning the trigger is often how you win."}},"families":[{"id":"beasts-of-the-wilds","title":"Beasts of the Wilds","lead":"These are the animals of the open country, from KR 1 to 90. They're natural creatures, but none of them are ordinary.","count":12,"ids":["thistlehare","gloamfox","ridgeback-ram","duskmane-lynx","bristleback-sow","lanternhorn-elk","two-jawed-bear","ironhide-aurochs","quillback-behemoth","stormmane-lion","antlermother","worldtusk"],"krMin":1,"krMax":90},{"id":"beasts-of-the-deep-places","title":"Beasts of the Deep Places","lead":"These are the creatures of caves, mines and the dark under the world, from KR 1 to 150. Most of them have never seen the sun.","count":12,"ids":["blind-crawler","echo-bat","pale-strider","lantern-grub","stonegut-mole","dripmaw","gloomhound","underlake-leech","hollowback-spider","burrowing-titan-grub","abyss-angler","under-root-serpent"],"krMin":1,"krMax":150},{"id":"sky-and-storm","title":"Sky and Storm","lead":"These are the creatures of open sky, mountain winds and storm clouds, from KR 1 to 200.","count":12,"ids":["gustling","razorwing-swift","thornshrike","stormcrow-flock","skyray","cloudstalker","stormherald-eagle","kitebeast","tempest-ray","sky-kraken","the-eye-of-the-storm","heavenspan-serpent"],"krMin":1,"krMax":200},{"id":"rivers-reefs-and-mires","title":"Rivers, Reefs and Mires","lead":"These are creatures of fresh water, salt water and everything in between, from KR 1 to 120. Most fights here happen half in the water, so check who can swim.","count":12,"ids":["reedsnapper","mirelight-toad","shockfin-eel","fenstrider","wallow-bull","coral-mimic","mire-gulper","tidecaller-crab","fogsinger","reefback","maelstrom-eel","the-undertow"],"krMin":1,"krMax":120},{"id":"dunes-and-wastes","title":"Dunes and Wastes","lead":"These are the creatures of deserts, salt flats and badlands, from KR 1 to 180. Out here, water is a weapon and shade is armour.","count":12,"ids":["sandskipper","glass-scorpion","dustjackal","saltcrust-beetle","mirage-cat","sun-eater-vulture","sandsea-ray","dust-devil","glasser","ruin-bearer-beetle","heatshimmer","the-salt-mother"],"krMin":1,"krMax":180},{"id":"the-frostlands","title":"The Frostlands","lead":"These are the creatures of tundra, glaciers and endless winter, from KR 1 to 250. Cold is the third combatant in every fight here.","count":12,"ids":["rimefinch","frost-vole-swarm","icefang-wolverine","whiteout-stalker","icetusk","glacier-crab","snowhulk","frostbloom","aurora-stag","floe-titan","permafrost-behemoth","the-long-winter"],"krMin":1,"krMax":250},{"id":"rot-and-mould","title":"Rot and Mould","lead":"These are fungi, moulds and the things they grow inside, from KR 1 to 160. Spores spread, so a fight here can follow the party home.","count":12,"ids":["puffcap","mouldmite-swarm","slimecrawler-slug","sporeback-boar","bloatcap","lichen-shambler","weeping-mould","mycelial-puppeteer","carrion-bloom","sporecrown-hulk","the-grey-network","blightheart"],"krMin":1,"krMax":160},{"id":"clockwork-and-arcane-constructs","title":"Clockwork and Arcane Constructs","lead":"These are things that were built rather than born, from KR 1 to 220. Constructs are immune to poison, bleed, fear and charm unless a block says otherwise. They're usually still following orders, so the person who gave them often matters more than the fight.","count":14,"ids":["cogmouse","tinkerbird-sentry","clerk-automaton","scuttle-lock","springheel-duellist","rune-lantern","bellhound","pendulum-guardian","inkwrought-scribe","orrery-engine","siege-walker","foundry-colossus","mainspring-titan","the-grand-mechanism"],"krMin":1,"krMax":220},{"id":"the-restless-dead","title":"The Restless Dead","lead":"These are the undead of Volume II, from KR 1 to 260. They're all immune to poison and fear, and have no need to breathe, eat or sleep. Each one is restless for a reason, and settling that reason is always an alternative to fighting.","count":16,"ids":["gravecrawler","lampwight","drowned-walker","gibbet-corpse","ossuary-swarm","weeping-widow","rotbell-carrier","boneweaver","gravewarden-knight","choir-of-the-dead","deathcart-driver","ossuary-giant","crypt-regent","grave-tide","the-unburied-host","gravefather"],"krMin":1,"krMax":260},{"id":"blood-and-bone","title":"Blood and Bone","lead":"These are creatures of living flesh, blood and marrow, from KR 2 to 190. None of them are undead: they're alive, and that's the horror of them.","count":10,"ids":["bloodtick","marrow-hound","clotspawn","ribcage-crawler","fleshtailor","crimson-weir","marrowmaw","the-sutured","heartdrum","crimsonmother"],"krMin":2,"krMax":190},{"id":"shadow-touched","title":"Shadow-touched","lead":"These are creatures of the dark flavour, from KR 1 to 240. Most of them are stronger in darkness and weaker in light. Light sources matter more in this family than any other.","count":12,"ids":["dimling","murkcat","silhouette","gloomweaver","umbral-stalker","dusk-knight","hush","eclipse-hound","penumbra","darkling-matron","the-long-shadow","starless"],"krMin":1,"krMax":240},{"id":"lightborn","title":"Lightborn","lead":"These are creatures of the light flavour, from KR 2 to 200. Light isn't the same as good: some of these are kind, some are cruel, and most are just very bright.","count":10,"ids":["glimmerwisp","prism-beetle","sunflare-hawk","glasswing-herald","halo-serpent","dawnwarden","lumen-arbiter","solar-moth","brightest","noon-eternal"],"krMin":2,"krMax":200},{"id":"dreamborn","title":"Dreamborn","lead":"These are creatures of sleep and the mind flavour, from KR 1 to 210. Many of them can be fought in the waking world or inside a dream; the block says which. A creature that dies in a dream wakes up at 1 HP with 1 level of exhaustion.","count":12,"ids":["nod-moth","lullaby-sprite","sleepwalker-husk","figment","sleepgrazer","fear-mirror","lucid-stalker","labyrinth-mind","the-hollow-smile","sleepwhale","morrow-sleeper","the-endless-dream"],"krMin":1,"krMax":210},{"id":"timeworn","title":"Timeworn","lead":"These are creatures that have come loose from time, from KR 3 to 280. They age things, repeat things and skip things. Keep a careful note of initiative: these monsters cheat it.","count":10,"ids":["moment-moth","witherjaw","stutterling","hourglass-golem","yesterdays-echo","epoch-tortoise","paradox-hound","chronophage","the-clockless","the-last-hour"],"krMin":3,"krMax":280},{"id":"crystalline","title":"Crystalline","lead":"These are creatures of living crystal and gemstone, from KR 2 to 230. Most of them are brittle to blunt damage and resist slashing. Sound and resonance hurt them in ways steel can't.","count":10,"ids":["shardling","resonance-bat","facet-lizard","shardhound","singing-spire","geode-maw","fracture-golem","lattice-spider","heart-of-the-mountain","the-growing-spire"],"krMin":2,"krMax":230},{"id":"living-metal","title":"Living Metal","lead":"These are creatures of the metal flavour, from KR 2 to 240. They're hard to cut and easy to rust, and most of them want what you're wearing. Fighters in heavy armour should be nervous.","count":10,"ids":["rustmite","coppercoil-snake","quicksilver-ooze","lodestone-hound","bladebriar","slag-brute","chain-coil","gilded-tyrant","lodemother","the-forge-born"],"krMin":2,"krMax":240},{"id":"groves-and-thickets","title":"Groves and Thickets","lead":"These are creatures of the root and life flavours, from KR 1 to 180. The woods defend themselves. Most of these won't chase you past the treeline.","count":10,"ids":["burrseed","snarevine","mossback-brock","hollow-stump-hermit","bramble-wolf","thicket-warden","seedcaster-willow","greenmaw-pitcher","the-old-hedge","firstwood"],"krMin":1,"krMax":180},{"id":"swarms-and-hives","title":"Swarms and Hives","lead":"These are creatures that act as one, from KR 2 to 190. Swarms take half damage from single-target attacks and double from area attacks, unless a block says otherwise. Hives have a queen, and the queen is usually the answer.","count":10,"ids":["gnat-cloud","paper-wasp-nest","emberfly-swarm","marching-ants","hive-guard-beetle","locust-tide","hivemind-queen","termite-colossus","the-murmuration","the-great-hive"],"krMin":2,"krMax":190},{"id":"giants-and-titanfolk","title":"Giants and Titanfolk","lead":"These are the big people of the world, from KR 6 to 300. Giants are people: most can be talked to, bargained with or tricked, and every one of them has somewhere they'd rather be.","count":10,"ids":["hillbrat","stone-tosser","bog-giant","cragherd","tidewader","cloudhauler","runebound-giant","stormbrow-titan","the-earthshaper","the-unmade-titan"],"krMin":6,"krMax":300},{"id":"planar-wanderers","title":"Planar Wanderers","lead":"These are visitors from other worlds, from KR 3 to 270. They follow different rules here, and they often don't understand ours. Many of them are lost, and some of them are shopping.","count":12,"ids":["driftling","threshold-cat","mirrorfolk-scout","wayfarer-merchant","gatewarden","inverted-knight","seam-stalker","skyreef-drifter","the-collector","starfall-herald","the-uninvited","the-other-world"],"krMin":3,"krMax":270},{"id":"wyrms-and-drakes","title":"Wyrms and Drakes","lead":"These are the dragon's lesser cousins, from KR 2 to 300. Drakes have legs and wings but no true breath; wyrms are long, limbless and very old. Use Volume I for true dragons. These fill the gaps around them.","count":12,"ids":["glidedrake","burrow-drake","thornback-drake","fen-wyrm","saddle-drake","hoardcrawler","twinflame-wyrm","echo-wyrm","moltwyrm","deepcoil-wyrm","comet-drake","worldcoil"],"krMin":2,"krMax":300},{"id":"tricksters-and-shapeshifters","title":"Tricksters and Shapeshifters","lead":"These are liars, mimics and changelings, from KR 2 to 130. Every one of these is a social encounter first. If the party ends up fighting one, it has usually already won something.","count":8,"ids":["pocketling","skinchanger-fox","the-wrong-neighbour","riddle-cat","faceless-courtier","thousand-mask","the-bargainer","the-grand-pretender"],"krMin":2,"krMax":130},{"id":"named","title":"Named Monsters","lead":"These are fifty individuals, from KR 2 to 260, each built from a Volume II creature. Most use the Boss template (KR ×2). The ones marked *Alpha Boss* use Alpha and Boss together (KR ×3). Where they live is left open on purpose, so you can drop them wherever you need them.\n\nEach named monster has phases at 66% and 33% HP. It takes lair actions on initiative 20 when fought at home. Each also has a hook to bring the party to it, and loot worth the trouble. Boss Tempo means it acts twice a round. Defiant is 2 below KR 50 and 3 from KR 50 up.","count":50,"ids":["grandmother-thistle","snuff","mister-pockets","old-lantern-jack","bellwether","the-hanged-juror","brindle-bess","snowgrin","prismeye","blink","old-clanger","lord-riposte","toller-grum","greymantle","clatterfang","ironjaw","shiver","whistler","old-deafear","mirebelly","sir-hollowcrest","ringlight","the-gentle-tailor","the-last-verse","hexquill","the-smiling-countess","stormcaller-ash","briarwarden-hale","the-hunger-wind","the-red-dancer","grandfather-cart","queen-hollow","the-grey-singer","sunglass","skyhorn","grinning-jack","the-last-ram","the-pale-regent","nobody","mother-mound","mister-fairdeal","king-aurum","moltking","the-unbound","mother-unlit","the-curator","whirlmaw","the-unbearable-dawn","grandfather-tick","his-majesty"],"krMin":2,"krMax":260}],"namedIntro":"These are fifty individuals, from KR 2 to 260, each built from a Volume II creature. Most use the Boss template (KR ×2). The ones marked *Alpha Boss* use Alpha and Boss together (KR ×3). Where they live is left open on purpose, so you can drop them wherever you need them.\n\nEach named monster has phases at 66% and 33% HP. It takes lair actions on initiative 20 when fought at home. Each also has a hook to bring the party to it, and loot worth the trouble. Boss Tempo means it acts twice a round. Defiant is 2 below KR 50 and 3 from KR 50 up.","index":{"intro":"All 300 entries, sorted by KR. Named monsters show the creature they're built from.","rows":[{"kr":1,"name":"Blind Crawler","family":"Beasts of the Deep Places","named":false,"builtFrom":null},{"kr":1,"name":"Burrseed","family":"Groves and Thickets","named":false,"builtFrom":null},{"kr":1,"name":"Cogmouse","family":"Clockwork and Arcane Constructs","named":false,"builtFrom":null},{"kr":1,"name":"Dimling","family":"Shadow-touched","named":false,"builtFrom":null},{"kr":1,"name":"Gravecrawler","family":"The Restless Dead","named":false,"builtFrom":null},{"kr":1,"name":"Gustling","family":"Sky and Storm","named":false,"builtFrom":null},{"kr":1,"name":"Nod-moth","family":"Dreamborn","named":false,"builtFrom":null},{"kr":1,"name":"Puffcap","family":"Rot and Mould","named":false,"builtFrom":null},{"kr":1,"name":"Reedsnapper","family":"Rivers, Reefs and Mires","named":false,"builtFrom":null},{"kr":1,"name":"Rimefinch","family":"The Frostlands","named":false,"builtFrom":null},{"kr":1,"name":"Sandskipper","family":"Dunes and Wastes","named":false,"builtFrom":null},{"kr":1,"name":"Thistlehare","family":"Beasts of the Wilds","named":false,"builtFrom":null},{"kr":2,"name":"Bloodtick","family":"Blood and Bone","named":false,"builtFrom":null},{"kr":2,"name":"Echo Bat","family":"Beasts of the Deep Places","named":false,"builtFrom":null},{"kr":2,"name":"Frost Vole Swarm","family":"The Frostlands","named":false,"builtFrom":null},{"kr":2,"name":"Glass Scorpion","family":"Dunes and Wastes","named":false,"builtFrom":null},{"kr":2,"name":"Glidedrake","family":"Wyrms and Drakes","named":false,"builtFrom":null},{"kr":2,"name":"Glimmerwisp","family":"Lig