rs gives advantage on saves; deafened creatures are immune.","kind":"creature","mechanics":{"weakPoints":[{"trait":2,"part":"Throat","hp":40,"each":false,"count":null}],"countdowns":[],"shifts":[]},"order":44},{"id":"reefback","name":"Reefback","kr":50,"volume":2,"family":"Rivers, Reefs and Mires","familyId":"rivers-reefs-and-mires","typeLine":"Beast, aquatic","tags":["aquatic"],"type":"Beast","description":"A sea turtle so old that a whole reef grows on its shell. Fishing villages have been built on it by mistake.","hp":430,"hpNote":null,"defence":5,"minHit":8,"speed":"20 ft, swim 50 ft","stats":{"str":1,"dex":18,"con":1,"int":14,"wis":8,"cha":15},"combat":{"melee":4,"ranged":null,"dodge":18,"disengage":18,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Bite","text":"Bite: 5d12.","multiattack":false,"recharge":null,"limit":null,"damage":["5d12"],"status":[]},{"name":"Flipper","text":"Flipper: everyone in a 30 ft arc takes 3d10 and is knocked prone.","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[]},{"name":"Dive","text":"*Dive* (when it chooses): everything on its back is in deep water.","multiattack":false,"recharge":null,"limit":"when it chooses","damage":[],"status":[]}],"traits":[{"name":"Solo","text":"*Solo*."},{"name":"Living Reef","text":"*Living Reef*: the reef on its shell holds 1d4 Coral Mimics."},{"name":"Countdown (4) – Dive","text":"*Countdown (4) – Dive*: if it's attacked, it dives after 4 rounds."}],"harvest":"Shell (legendary armour plating), reef treasures.","role":"Solo","wants":"To sleep in warm shallows.","tactics":"Doesn't care about you until you hurt it, then it dives.","tell":"the island starts to tilt.","exploit":"it's gentle, and warm water keeps it asleep.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[{"trait":2,"count":4,"unit":"rounds","effect":"Dive"}],"shifts":[]},"order":45},{"id":"maelstrom-eel","name":"Maelstrom Eel","kr":80,"volume":2,"family":"Rivers, Reefs and Mires","familyId":"rivers-reefs-and-mires","typeLine":"Beast, aquatic","tags":["aquatic"],"type":"Beast","description":"A sea eel as long as a warship. It swims in tight circles until the sea becomes a whirlpool.","hp":680,"hpNote":null,"defence":4,"minHit":9,"speed":"swim 90 ft","stats":{"str":1,"dex":5,"con":2,"int":15,"wis":7,"cha":15},"combat":{"melee":4,"ranged":null,"dodge":12,"disengage":10,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Bite 5d12 and Tail Crush 4d12, +2d2 lightning stun.","multiattack":true,"recharge":null,"limit":null,"damage":["5d12","4d12"],"status":[{"dice":"2d2","n":2,"status":"lightning stun"}]},{"name":"Discharge","text":"*Discharge* (3-turn recharge): everything in the water within 120 ft takes 8d10 lightning.","multiattack":false,"recharge":3,"limit":null,"damage":["8d10"],"status":[]}],"traits":[{"name":"Solo","text":"*Solo*, Defiant 2."},{"name":"Tempo","text":"*Tempo*: it acts twice a round."},{"name":"Countdown (5) – Maelstrom","text":"*Countdown (5) – Maelstrom*: after 5 rounds of circling, a whirlpool 300 ft across forms. Ships in it are pulled to the centre and sink."}],"harvest":"Charge organ (legendary lightning core).","role":"Solo","wants":"Ships.","tactics":"Circles to build the maelstrom while shocking anything in the water.","tell":"the sea starts to spin.","exploit":"hit it hard enough (100 in a round) and it has to stop circling, which resets the countdown.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[{"trait":2,"count":5,"unit":"rounds","effect":"Maelstrom"}],"shifts":[]},"order":46},{"id":"the-undertow","name":"The Undertow","kr":120,"volume":2,"family":"Rivers, Reefs and Mires","familyId":"rivers-reefs-and-mires","typeLine":"Elemental","tags":[],"type":"Elemental","description":"A living current that pulls ships, swimmers and whole harbours out to sea. It has no body you can see, only a cold, moving darkness.","hp":1080,"hp