cks":[{"name":"Bake","text":"*Bake* (×2 a round): one creature within 60 ft takes 5d10 fire and 1 level of thirst.","multiattack":false,"recharge":null,"limit":"×2 a round","damage":["5d10"],"status":[]},{"name":"Mirage Field","text":"*Mirage Field* (3-turn recharge): everyone within 120 ft makes a WIS save or sees allies as enemies for 1 turn.","multiattack":false,"recharge":3,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Solo","text":"*Solo*, Defiant 2."},{"name":"Shimmer","text":"*Shimmer*: it's invisible in sunlight."},{"name":"Shift (Day/Night)","text":"*Shift (Day/Night)*: at night it's visible, slow (20 ft) and its Min hit drops to 4."}],"harvest":"Bottled heat (legendary fire core).","role":"Solo","wants":"Water, from any source.","tactics":"Bakes the party while they turn on each other.","tell":"waterskins start to steam.","exploit":"wait for night.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[{"trait":2,"modes":["Day","Night"]}]},"order":58},{"id":"the-salt-mother","name":"The Salt Mother","kr":180,"volume":2,"family":"Dunes and Wastes","familyId":"dunes-and-wastes","typeLine":"Beast","tags":[],"type":"Beast","description":"A vast, salt-crusted thing that swims beneath the deep desert. When she surfaces, she raises a sandstorm that buries cities.","hp":1650,"hpNote":null,"defence":6,"minHit":12,"speed":"burrow 80 ft","stats":{"str":1,"dex":10,"con":1,"int":12,"wis":5,"cha":10},"combat":{"melee":3,"ranged":null,"dodge":14,"disengage":12,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Bite 5d20 (swallowed, 4d10 acid a turn) and Salt Spray, a 60 ft cone, 6d10 and 2 levels of thirst.","multiattack":true,"recharge":null,"limit":null,"damage":["5d20","4d10","6d10"],"status":[]},{"name":"Breach","text":"*Breach* (3-turn recharge): she rises under a 100 ft area, 10d10 and everything is knocked prone.","multiattack":false,"recharge":3,"limit":null,"damage":["10d10"],"status":[]}],"traits":[{"name":"Set piece","text":"*Set piece*."},{"name":"Tempo","text":"*Tempo*: she acts three times a round."},{"name":"Countdown (8) – The Great Storm","text":"*Countdown (8) – The Great Storm*: after 8 rounds the sandstorm covers everything for a mile."},{"name":"Weak Points – Gills (120 HP each, ×4)","text":"*Weak Points – Gills (120 HP each, ×4)*: breaking each gill adds 2 to the countdown."}],"harvest":"Salt-pearl (god-tier sand core), crust (legendary armour).","role":"Set piece","wants":"To breathe.","tactics":"She's surfacing to breathe, and the storm is just her breath. The party has to delay the countdown or move the city.","tell":"wells across the region run salty for a week.","exploit":"she'll go back under for water. Flood her gills and she dives.","kind":"creature","mechanics":{"weakPoints":[{"trait":3,"part":"Gills","hp":120,"each":true,"count":4}],"countdowns":[{"trait":2,"count":8,"unit":"rounds","effect":"The Great Storm"}],"shifts":[]},"order":59},{"id":"rimefinch","name":"Rimefinch","kr":1,"volume":2,"family":"The Frostlands","familyId":"the-frostlands","typeLine":"Beast, flier","tags":["flier"],"type":"Beast","description":"A tiny white finch whose song frosts the air. Flocks of them make a clearing cold enough to hurt.","hp":5,"hpNote":null,"defence":0,"minHit":0,"speed":"10 ft, fly 50 ft","stats":{"str":19,"dex":4,"con":14,"int":17,"wis":9,"cha":13},"combat":{"melee":9,"ranged":null,"dodge":8,"disengage":5,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Peck","text":"Peck: 1d4 cold.","multiattack":false,"recharge":null,"limit":null,"damage":["1d4"],"status":[]}],"traits":[{"name":"Frost Song","text":"*Frost Song*: while three or more are within 30 ft of each other, the area counts as freezing (+1d2 frost to anyone who doesn't move each turn)."}],"harvest":"Frost feathers (keep food cold).","role":"Swarm","wants":"Seeds and cold weather.","tactics":"Harmless alone; in a flock, they make standing still dangerous.","tell":"a sudden chill and tiny bird song.","exploit":"any fire scatters them.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":60},{"id":"frost-vole-swarm","name":"Frost Vole Swarm","kr":2,"volume":2,"family":"The Frostlands","familyId":"the-frostlands","typeLine":"Beast, swarm","tags":["swarm"],"type":"Beast","description":"Hundreds of white voles that tunnel under the snow and boil up around anyone who stops.","hp":18,"hpNote":null,"defence":0,"minHit":0,"speed":"30 ft, burrow 20 ft (snow)","stats":{"str":16,"dex":7,"con":12,"int":19,"wis":11,"cha":19},"combat":{"melee":9,"ranged":null,"dodge":15,"disengage":13,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Nibbles","text":"Nibbles: 1d8 to everyone in its space.","multiattack":false,"recharge":null,"limit":null,"damage":["1d8"],"status":[]}],"traits":[{"name":"Swarm","text":"*Swarm*."},{"name":"Under the Snow","text":"*Under the Snow*: it can't be targeted while burrowed."}],"harvest":"Nothing of value.","role":"Swarm","wants":"Warm bodies to nest against.","tactics":"Boils up under a sleeping camp.","tell":"the snow trembles in little lines.","exploit":"sleep on rock or ice.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":61},{"id":"icefang-wolverine","name":"Icefang Wolverine","kr":4,"volume":2,"family":"The Frostlands","familyId":"the-frostlands","typeLine":"Beast","tags":[],"type":"Beast","description":"A wolverine with teeth of rime ice and a temper to match. It steals from traps and fights things ten times its size.","hp":36,"hpNote":null,"defence":2,"minHit":1,"speed":"35 ft, climb 20 ft","stats":{"str":9,"dex":7,"con":7,"int":15,"wis":9,"cha":17},"combat":{"melee":8,"ranged":null,"dodge":12,"disengage":10,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Bite 1d8 cold, +1d2 frost, and Claws 1d6.","multiattack"