","Blizzard"]}]},"order":63},{"id":"icetusk","name":"Icetusk","kr":9,"volume":2,"family":"The Frostlands","familyId":"the-frostlands","typeLine":"Beast, amphibious","tags":["amphibious"],"type":"Beast","description":"A great, blubbery beast with tusks like ice picks. It hauls itself out of freezing seas to fight for its beach.","hp":85,"hpNote":null,"defence":3,"minHit":3,"speed":"20 ft, swim 40 ft","stats":{"str":4,"dex":16,"con":4,"int":18,"wis":12,"cha":16},"combat":{"melee":7,"ranged":null,"dodge":17,"disengage":16,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Tusks","text":"Tusks: 2d10.","multiattack":false,"recharge":null,"limit":null,"damage":["2d10"],"status":[]},{"name":"Belly Slam","text":"*Belly Slam*: everyone within 10 ft takes 2d8 and is knocked prone.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]}],"traits":[{"name":"Blubber","text":"*Blubber*: cold damage doesn't hurt it, and it has resistance to blunt damage."}],"harvest":"Tusks (ivory), blubber (lamp oil for a winter).","role":"Brute","wants":"Its beach.","tactics":"Slams, then gores whoever is down.","tell":"it roars with its head thrown back.","exploit":"it's slow on land, so you can outrun it.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":64},{"id":"glacier-crab","name":"Glacier Crab","kr":13,"volume":2,"family":"The Frostlands","familyId":"the-frostlands","typeLine":"Beast","tags":[],"type":"Beast","description":"A crab with a shell of blue ice that it grows by freezing water onto its back. It wedges itself into glacier crevasses.","hp":115,"hpNote":null,"defence":4,"minHit":4,"speed":"30 ft, climb 30 ft","stats":{"str":5,"dex":14,"con":4,"int":19,"wis":12,"cha":19},"combat":{"melee":7,"ranged":null,"dodge":16,"disengage":15,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Ice Claws ×2, 2d8 cold each (grabbed).","multiattack":