omething perfect.","tactics":"Stitches people together, then cuts at them.","tell":"it measures you with its fingers.","exploit":"cut the threads, break the spool.","kind":"creature","mechanics":{"weakPoints":[{"trait":0,"part":"Spool","hp":25,"each":false,"count":null}],"countdowns":[],"shifts":[]},"order":118},{"id":"crimson-weir","name":"Crimson Weir","kr":25,"volume":2,"family":"Blood and Bone","familyId":"blood-and-bone","typeLine":"Ooze","tags":[],"type":"Ooze","description":"A pool of living blood the size of a pond. It rises in waves to pull swimmers and animals in.","hp":210,"hpNote":null,"defence":1,"minHit":3,"speed":"20 ft, swim 40 ft","stats":{"str":4,"dex":14,"con":3,"int":17,"wis":10,"cha":18},"combat":{"melee":6,"ranged":null,"dodge":16,"disengage":15,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Wave","text":"*Wave*: a 20 ft line, 3d10 and pulled 20 ft into the pool (STR save resists).","multiattack":false,"recharge":null,"limit":null,"damage":["3d10"],"status":[]},{"name":"Drown in Blood","text":"*Drown in Blood*: creatures in the pool take 3d8 a turn and it heals that much.","multiattack":false,"recharge":null,"limit":null,"damage":["3d8"],"status":[]}],"traits":[{"name":"Immune","text":"*Immune*: slashing and piercing."},{"name":"Coagulate","text":"*Coagulate*: cold damage makes it sluggish (no Wave next turn)."}],"harvest":"Living blood (a life-school legendary reagent if taken from its heart).","role":"Controller","wants":"To grow.","tactics":"Pulls everything in and drowns it.","tell":"the pond is warm.","exploit":"cold.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":119},{"id":"marrowmaw","name":"Marrowmaw","kr":33,"volume":2,"family":"Blood and Bone","familyId":"blood-and-bone","typeLine":"Beast","tags":[],"type":"Beast","description":"A hulking, hairless predator with a jaw built to crack bones. When it gets hold of something, the countdown starts.","hp":280,"hpNote":nu