rait":1,"modes":["form"]}]},"order":247},{"id":"the-bargainer","name":"The Bargainer","kr":55,"volume":2,"family":"Tricksters and Shapeshifters","familyId":"tricksters-and-shapeshifters","typeLine":"Fey","tags":[],"type":"Fey","description":"A smiling stranger at a crossroads who'll give you anything you want, for a price that seems fair at the time.","hp":470,"hpNote":null,"defence":3,"minHit":7,"speed":"40 ft","stats":{"str":4,"dex":4,"con":3,"int":1,"wis":2,"cha":1},"combat":{"melee":4,"ranged":null,"dodge":10,"disengage":6,"casting":3},"combatOrder":["melee","casting","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Contract Blade ×2, 4d10 each.","multiattack":true,"recharge":null,"limit":null,"damage":["4d10"],"status":[]},{"name":"Call in a Debt","text":"*Call in a Debt*: a creature who's made a deal with it makes a CHA save or pays the price now (the GM decides what).","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Solo","text":"*Solo*."},{"name":"Contracts (Weak Points, 50 HP each)","text":"*Contracts (Weak Points, 50 HP each)*: every deal it has made is a contract it carries. Destroying a contract frees the debtor, and the Bargainer loses 50 max HP."},{"name":"Bound by Word","text":"*Bound by Word*: it can't break a deal."}],"harvest":"Its contracts, including some very interesting signatures.","role":"Solo","wants":"Everyone in its debt.","tactics":"It never fights fair, but it always fights by the letter.","tell":"it already knows your name.","exploit":"the small print cuts both ways.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":248},{"id":"the-grand-pretender","name":"The Grand Pretender","kr":130,"volume":2,"family":"Tricksters and Shapeshifters","familyId":"tricksters-and-shapeshifters","typeLine":"Shapeshifter","tags":[],"type":"Shapeshifter","description":"The ruler of the realm isn't the ruler of the realm. They haven't been for twenty years. The thing on the throne is very good at pretending.","hp":1170,"hpNote":null,"defence":4,"minHit":11,"speed":"40 ft","stats":{"str":2,"dex":3,"con":2,"int":1,"wis":1,"cha":1},"combat":{"melee":3,"ranged":null,"dodge":9,"disengage":5,"casting":2},"combatOrder":["melee","casting","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: True Form Claws ×3, 5d12 each.","multiattack":true,"recharge":null,"limit":null,"damage":["5d12"],"status":[]},{"name":"Royal Command","text":"*Royal Command* (3-turn recharge): every guard, soldier and courtier within a mile attacks whoever it points at.","multiattack":false,"recharge":3,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Solo","text":"*Solo*, Defiant 2."},{"name":"The Throne (Weak Point)","text":"*The Throne (Weak Point)*: while anyone believes it's the real ruler, it regains 50 HP a round. Proof of the deception, shown publicly, ends that."},{"name":"Countdown (3 sessions) – Succession","text":"*Countdown (3 sessions) – Succession*: it's about to name its heir, another of its kind."}],"harvest":"The real ruler, imprisoned somewhere for twenty years.","role":"Solo","wants":"The realm, forever.","tactics":"The party has to prove it's a fake before they can even fight it.","tell":"the ruler hasn't aged a day in twenty years.","exploit":"the real ruler is alive and has a secret only they know.","kind":"creature","mechanics":{"weakPoints":[],"countdowns":[{"trait":2,"count":3,"unit":"sessions","effect":"Succession"}],"shifts":[]},"order":249},{"id":"grandmother-thistle","name":"Grandmother Thistle","kr":2,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Thistlehare","tags":[],"type":"Boss Thistlehare","description":"A grizzled old hare with a crown of white spines, the matriarch of the biggest warren for miles. Every hare in the hedges answers to her.","hp":16,"hpNote":null,"defence":0,"minHit":0,"speed":"50 ft","stats":{"str":16,"dex":5,"con":13,"int":18,"wis":9,"cha":