ll,"role":null,"wants":null,"tactics":"Lights up runners and freezes them.","tell":"\"Halt! Who goes there?\"","exploit":"his logbook. Solve his murder and he finishes his shift.","kind":"named","templates":["Alpha","Boss"],"builtFrom":"Lampwight","phases":[{"at":"66%","text":"he calls \"Halt!\" and 1d4 Lampwights come."},{"at":"33%","text":"his lantern turns red, and Cold Lantern hits everyone in a 15 ft line."}],"lair":"His old watchtower. *Lair actions*: the bell rings (everyone makes a WIS save or is frightened for 1 turn), or the doors slam and lock.","hook":"People out after curfew are found frozen in the streets, all of them still holding a light.","loot":"Jack's lantern (shows invisible things within 60 ft). His logbook, which names the crime that killed him.","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":253,"builtFromId":"lampwight","templateCheck":"exact"},{"id":"bellwether","name":"Bellwether","kr":6,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Ridgeback Ram","tags":[],"type":"Boss Ridgeback Ram","description":"A huge old ram with a cracked bell around its neck and horns like a battering ram. He's knocked a dozen climbers off the pass.","hp":56,"hpNote":null,"defence":2,"minHit":1,"speed":"40 ft, climb 40 ft","stats":{"str":6,"dex":10,"con":6,"int":17,"wis":11,"cha":16},"combat":{"melee":8,"ranged":null,"dodge":17,"disengage":13,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Ram","text":"Ram: 1d10, pushed 10 ft.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Charge","text":"*Charge*: after 20 ft, 2d10, pushed 20 ft.","multiattack":false,"recharge":null,"limit":null,"damage":["2d10"],"status":[]}],"traits":[{"name":"Boss","text":"*Boss*: Defiant 2, Boss Tempo."},{"name":"Sure-footed","text":"*Sure-footed*."}],"harvest":null,"role":null,"wants":null,"tactics":"Charges people towards the drop.","tell":"the bell's clang echoes off the rocks.","exploit":"rope the party together.","kind":"named","templates":["Boss"],"builtFrom":"Ridgeback Ram","phases":[{"at":"66%","text":"his bell rings, and 1d4 Ridgeback Rams arrive."},{"at":"33%","text":"every Ram pushes 10 ft further."}],"lair":"A narrow mountain pass. *Lair actions*: loose rocks fall on one creature (1d10, DEX save), or the ledge crumbles under someone (DEX save or slide 10 ft towards the edge).","hook":"The only pass over the mountain has been closed for a month. Merchants are paying well to have it opened.","loot":"Bellwether's horns (a shield that pushes attackers back 5 ft when they hit it). His bell, which calls goats.","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":254,"builtFromId":"ridgeback-ram","templateCheck":"exact"},{"id":"the-hanged-juror","name":"The Hanged Juror","kr":8,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Gibbet Corpse","tags":[],"type":"Boss Gibbet Corpse","description":"The man who sat on the jury that hanged an innocent woman, then hanged himself for it. He swings at the crossroads waiting for the others.","hp":72,"hpNote":null,"defence":3,"minHit":2,"speed":"0 ft (he swings)","stats":{"str":9,"dex":12,"con":7,"int":18,"wis":12,"cha":18},"combat":{"melee":8,"ranged":null,"dodge":15,"disengage":null,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"name":"Bony Grab","text":"Bony Grab: reach 15 ft, 1d10 (grabbed).","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]},{"name":"Pull In","text":"*Pull In*: 1d10 a turn.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]}],"traits":[{"name":"Boss","text":"*Boss*: Defiant 2, Boss Tempo."},{"name":"Undead","text":"*Undead*."},{"name":"Weak Point – Chain (30 HP)","text":"*Weak Point – Chain (30 HP)*."}],"harvest":null,"role":null,"wants":null,"tactics":"He wants the other jurors.","tell":"a creaking chain on a still night.","exploit":"clear the woman's 