:["Boss"],"builtFrom":"Fleshtailor","phases":[{"at":"66%","text":"it stitches two of its works together into one, at full HP."},{"at":"33%","text":"it tries to stitch itself to a party member (CON save), and shares their HP until cut free."}],"lair":"A workshop of half-finished creations. *Lair actions*: thread lashes out (restrained), or a creation twitches awake.","hook":"People are disappearing. Some come back, improved. Their families don't want them.","loot":"The Tailor's needles (a surgeon's kit that closes any wound). Its thread.","mechanics":{"weakPoints":[{"trait":1,"part":"Spool","hp":50,"each":false,"count":null}],"countdowns":[],"shifts":[]},"order":272,"builtFromId":"fleshtailor","templateCheck":"exact"},{"id":"the-last-verse","name":"The Last Verse","kr":40,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Choir of the Dead","tags":[],"type":"Boss Choir of the Dead","description":"Five ghosts who were singing the last verse of a hymn when their chapel burned. They're still singing it, louder every year.","hp":340,"hpNote":"five singers, 68 HP each","defence":0,"minHit":0,"speed":"fly 20 ft","stats":{"str":20,"dex":9,"con":10,"int":10,"wis":6,"cha":4},"combat":{"melee":null,"ranged":null,"dodge":13,"disengage":11,"casting":6},"combatOrder":["casting","dodge","disengage"],"attacks":[{"name":"Hymn","text":"*Hymn*: 1d10 soul damage for each singer, within 60 ft.","multiattack":false,"recharge":null,"limit":null,"damage":["1d10"],"status":[]}],"traits":[{"name":"Boss","text":"*Boss*: Defiant 2, Boss Tempo (Hymn twice a round)."},{"name":"Incorporeal","text":"*Incorporeal*."},{"name":"Harmony","text":"*Harmony*."}],"harvest":null,"role":null,"wants":null,"tactics":"It's a puzzle with a timer.","tell":"the singing.","exploit":"find the last page and sing it with them.","kind":"named","templates":["Boss"],"builtFrom":"Choir of the Dead","phases":[{"at":"66%","text":"the hymn reaches 120 ft, and the burned chapel appears around the party."},{"at":"33%","text":"the fire returns, and the chapel deals 2d10 fire a round to everyone inside."}],"lair":"A burned chapel. *Lair actions*: a burning beam falls (2d10), or the doors slam shut.","hook":"Every year on the same night, the burned chapel is seen whole again, and anyone who goes in doesn't come out.","loot":"The last page of the hymn (sung, it lays any ghost to rest). The chapel's silver.","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":273,"builtFromId":"choir-of-the-dead","templateCheck":"exact"},{"id":"hexquill","name":"Hexquill","kr":42,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Inkwrought Scribe","tags":[],"type":"Boss Inkwrought Scribe","description":"A spell-copying automaton that has copied every spell in a great library. It's decided the library is its own.","hp":350,"hpNote":null,"defence":3,"minHit":4,"speed":"30 ft","stats":{"str":10,"dex":7,"con":7,"int":3,"wis":7,"cha":12},"combat":{"melee":7,"ranged":null,"dodge":13,"disengage":11,"casting":5},"combatOrder":["melee","casting","dodge","disengage"],"attacks":[{"name":"Quill","text":"Quill: 2d8.","multiattack":false,"recharge":null,"limit":null,"damage":["2d8"],"status":[]},{"name":"Spellcasting","text":"*Spellcasting*: tiers 1–5 of any four schools.","multiattack":false,"recharge":null,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Boss","text":"*Boss*: Defiant 2, Boss Tempo."},{"name":"Construct","text":"*Construct*."},{"name":"Copy","text":"*Copy*."},{"name":"Weak Point – Ink reservoir (60 HP)","text":"*Weak Point – Ink reservoir (60 HP)*."}],"harvest":null,"role":null,"wants":null,"tactics":"It copies your best spell and throws it back.","tell":"it starts writing as you start casting.","exploit":"it hates fire near its books.","kind":"named","templates":["Boss"],"builtFrom":"Inkwrought Scribe","phases":[{"at":"66%","text":"it writes spells into the air that go off a round later (a countdown of 1 on each)."},{"at":"33%","text":"