ng":4},"combatOrder":["melee","casting","dodge","disengage"],"attacks":[{"name":"Multiattack","text":"Multiattack: Golden Sceptre ×2, 4d10 each.","multiattack":true,"recharge":null,"limit":null,"damage":["4d10"],"status":[]},{"name":"Midas Touch","text":"*Midas Touch* (2-turn recharge).","multiattack":false,"recharge":2,"limit":null,"damage":[],"status":[]}],"traits":[{"name":"Boss","text":"*Boss*: Defiant 3, Boss Tempo."},{"name":"Greed","text":"*Greed*."},{"name":"Golden Body","text":"*Golden Body*."}],"harvest":null,"role":null,"wants":null,"tactics":"Turns the greedy to gold.","tell":"coins slide towards him.","exploit":"throw away your gold. Unwish his wish and the kingdom returns.","kind":"named","templates":["Boss"],"builtFrom":"Gilded Tyrant","phases":[{"at":"66%","text":"his golden subjects come to life (2d4, KR 10 each)."},{"at":"33%","text":"Midas Touch works on everything in a 20 ft area."}],"lair":"A golden palace. *Lair actions*: the floor turns to gold under a creature (restrained, STR save), or coins rain from the ceiling (2d10).","hook":"A golden city has been found in the hills. Treasure hunters go in. They don't come out, but more gold statues appear.","loot":"The gold (it's cursed until Aurum is broken). The wish that made him, carved in a gold tablet.","mechanics":{"weakPoints":[],"countdowns":[],"shifts":[]},"order":291,"builtFromId":"gilded-tyrant","templateCheck":"exact"},{"id":"moltking","name":"Moltking","kr":124,"volume":2,"family":"Named Monsters","familyId":"named","typeLine":"Boss Moltwyrm","tags":[],"type":"Boss Moltwyrm","description":"A Moltwyrm so old it's shed a hundred skins. Its sheds lie in a valley like a field of empty wyrms, and every one of them can rise.","hp":1040,"hpNote":null,"defence":4,"minHit":8,"speed":"40 ft, burrow 20 ft","stats":{"str":1,"dex":10,"con":1,"int":10,"wis":6,"cha":12},"combat":{"melee":4,"ranged":null,"dodge":15,"disengage":13,"casting":null},"combatOrder":["melee","dodge","disengage"],"attacks":[{"na